                [ 'products', '8169201631445,9163846877397,9089720189141' ],
                [ 'h2', 'Laser-cut wedding invitations: tips for a small stationery studio' ],
                [ 'p', 'A laser lets a small studio make every piece different without paying for a die – an advantage for invitations, place cards and short packaging runs.' ],
